char *route_line(const char **parts, size_t n) {
    size_t total = 1;
    for (size_t i = 0; i < n; i++) {
        total += strlen(parts[i]) + 1;
    }
    char *out = malloc(total);
    char *end = out;
    for (size_t i = 0; i < n; i++) {
        if (i > 0) {
            *end++ = ',';
        }
        size_t len = strlen(parts[i]);
        memcpy(end, parts[i], len);
        end += len;
    }
    *end = '\0';
    return out;
}

