#include <stdlib.h>
#include <string.h>

char *route_line(const char **parts, size_t n) {
    char *out = malloc(1);
    out[0] = '\0';
    for (size_t i = 0; i < n; i++) {
        out = realloc(out, strlen(out) + strlen(parts[i]) + 2);
        if (i > 0) {
            strcat(out, ",");
        }
        strcat(out, parts[i]);
    }
    return out;
}

