size_t first_seen_codes(const int *in, size_t n, int *out) {
    size_t cap = 16;
    while (cap < 2 * n) {
        cap <<= 1;
    }
    unsigned char *used = calloc(cap, 1);
    int *slots = malloc(cap * sizeof(int));
    size_t count = 0;
    for (size_t i = 0; i < n; i++) {
        size_t h = ((unsigned)in[i] * 2654435761u) & (cap - 1);
        while (used[h] && slots[h] != in[i]) {
            h = (h + 1) & (cap - 1);
        }
        if (!used[h]) {
            used[h] = 1;
            slots[h] = in[i];
            out[count++] = in[i];
        }
    }
    free(used);
    free(slots);
    return count;
}

